// src/App.js
import React, { useState, useEffect } from 'react';
import {
  Card,
  Typography,
  Grid,
  Slider,
  Button,
  Alert,
  CircularProgress,
  Box,
  Divider,
  Chip,
  LinearProgress,
  TextField,
  InputAdornment,
  IconButton,
  Drawer,
  List,
  ListItem,
  ListItemText,
  ListItemIcon,
  AppBar,
  Toolbar,
  Avatar
} from '@mui/material';
import {
  ResponsiveContainer,
  AreaChart,
  Area,
  PieChart,
  Pie,
  Cell,
  CartesianGrid,
  XAxis,
  YAxis,
  Tooltip as RechartsTooltip
} from 'recharts';
import { io } from 'socket.io-client';
import MenuIcon from '@mui/icons-material/Menu';
import DashboardIcon from '@mui/icons-material/Dashboard';
import SettingsIcon from '@mui/icons-material/Settings';
import DeviceHubIcon from '@mui/icons-material/DeviceHub';
import LogoutIcon from '@mui/icons-material/Logout';
import AddIcon from '@mui/icons-material/Add';
import { useAuth } from './context/AuthContext';
import Auth from './components/Auth';
import axios from 'axios';

const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:3001';

const COLORS = {
  primary: '#2563eb',
  success: '#10b981',
  warning: '#f59e0b',
  danger: '#ef4444',
  dark: '#1f2937',
  light: '#f3f4f6'
};

function App() {
  const { user, logout, isAuthenticated, loading } = useAuth();
  const [devices, setDevices] = useState([]);
  const [selectedDevice, setSelectedDevice] = useState(null);
  const [history, setHistory] = useState([]);
  const [socket, setSocket] = useState(null);
  const [drawerOpen, setDrawerOpen] = useState(false);
  const [configOpen, setConfigOpen] = useState(false);
  const [alert, setAlert] = useState(null);
  const [newDeviceId, setNewDeviceId] = useState('');
  const [newDeviceName, setNewDeviceName] = useState('');

  // Configuración del dispositivo seleccionado
  const [minLevel, setMinLevel] = useState(20);
  const [maxLevel, setMaxLevel] = useState(80);
  const [tankHeight, setTankHeight] = useState(100);
  const [inputMinLevel, setInputMinLevel] = useState('');
  const [inputMaxLevel, setInputMaxLevel] = useState('');
  const [inputTankHeight, setInputTankHeight] = useState('');

  useEffect(() => {
    if (isAuthenticated) {
      fetchDevices();
    }
  }, [isAuthenticated]);

  useEffect(() => {
    if (selectedDevice && isAuthenticated) {
      fetchDeviceStatus(selectedDevice.deviceId);
      fetchDeviceHistory(selectedDevice.deviceId);
      connectWebSocket(selectedDevice.deviceId);
    }
  }, [selectedDevice]);

  const fetchDevices = async () => {
    try {
      const response = await axios.get(`${API_URL}/api/devices`);
      setDevices(response.data);
      if (response.data.length > 0 && !selectedDevice) {
        setSelectedDevice(response.data[0]);
      }
    } catch (error) {
      console.error('Error cargando dispositivos:', error);
    }
  };

  const fetchDeviceStatus = async (deviceId) => {
    try {
      const response = await axios.get(`${API_URL}/api/status/${deviceId}`);
      setSelectedDevice(prev => ({ ...prev, currentStatus: response.data }));
      setMinLevel(prev => response.data.minLevel || prev);
      setMaxLevel(prev => response.data.maxLevel || prev);
      setTankHeight(prev => response.data.tankHeight || prev);
    } catch (error) {
      console.error('Error cargando estado:', error);
    }
  };

  const fetchDeviceHistory = async (deviceId) => {
    try {
      const response = await axios.get(`${API_URL}/api/history/${deviceId}`);
      setHistory(response.data);
    } catch (error) {
      console.error('Error cargando historial:', error);
    }
  };

  const connectWebSocket = (deviceId) => {
    if (socket) socket.close();
    const newSocket = io(API_URL);
    newSocket.on(`status_update_${deviceId}`, (data) => {
      setSelectedDevice(prev => ({ ...prev, currentStatus: data }));
    });
    setSocket(newSocket);
    return () => newSocket.close();
  };

  const registerDevice = async () => {
    if (!newDeviceId) {
      setAlert({ type: 'error', message: 'Ingresa un ID para el dispositivo' });
      return;
    }
    try {
      await axios.post(`${API_URL}/api/devices/register`, {
        deviceId: newDeviceId,
        name: newDeviceName || 'Mi Tanque'
      });
      setAlert({ type: 'success', message: 'Dispositivo registrado correctamente' });
      setNewDeviceId('');
      setNewDeviceName('');
      fetchDevices();
      setTimeout(() => setAlert(null), 3000);
    } catch (error) {
      setAlert({ type: 'error', message: error.response?.data?.error || 'Error al registrar' });
    }
  };

  const saveConfig = async () => {
    if (!selectedDevice) return;
    const minVal = inputMinLevel === '' ? minLevel : parseInt(inputMinLevel);
    const maxVal = inputMaxLevel === '' ? maxLevel : parseInt(inputMaxLevel);
    const heightVal = inputTankHeight === '' ? tankHeight : parseInt(inputTankHeight);

    if (minVal >= maxVal) {
      setAlert({ type: 'error', message: 'El nivel mínimo debe ser menor que el máximo' });
      return;
    }

    try {
      await axios.post(`${API_URL}/api/config`, {
        deviceId: selectedDevice.deviceId,
        minLevel: minVal,
        maxLevel: maxVal,
        tankHeight: heightVal
      });
      setAlert({ type: 'success', message: 'Configuración guardada' });
      setTimeout(() => setAlert(null), 3000);
    } catch (error) {
      setAlert({ type: 'error', message: 'Error al guardar configuración' });
    }
  };

  if (loading) {
    return (
      <Box display="flex" justifyContent="center" alignItems="center" minHeight="100vh">
        <CircularProgress size={60} />
      </Box>
    );
  }

  if (!isAuthenticated) {
    return <Auth />;
  }

  const levelPercentage = selectedDevice?.currentStatus?.level || 0;
  const pumpStatus = selectedDevice?.currentStatus?.pumpStatus || false;

  const chartData = history.slice(-20).map(item => ({
    time: new Date(item.timestamp).toLocaleTimeString(),
    level: item.level
  }));

  const pumpData = [
    { name: 'Bomba ON', value: pumpStatus ? 1 : 0, color: COLORS.success },
    { name: 'Bomba OFF', value: pumpStatus ? 0 : 1, color: COLORS.danger }
  ];

  const stats = {
    avgLevel: history.length ? (history.reduce((sum, h) => sum + h.level, 0) / history.length).toFixed(1) : 0,
    maxLevel: history.length ? Math.max(...history.map(h => h.level)) : 0,
    minLevel: history.length ? Math.min(...history.map(h => h.level)) : 0
  };

  return (
    <Box sx={{ display: 'flex', minHeight: '100vh', bgcolor: COLORS.light }}>
      <AppBar position="fixed" sx={{ zIndex: 1201 }}>
        <Toolbar>
          <IconButton color="inherit" edge="start" onClick={() => setDrawerOpen(true)} sx={{ mr: 2 }}>
            <MenuIcon />
          </IconButton>
          <Typography variant="h6" sx={{ flexGrow: 1 }}>
            💧 Control de Tanque
          </Typography>
          <Box display="flex" alignItems="center" gap={1}>
            <Chip label={user?.username} size="small" />
            <IconButton color="inherit" onClick={logout}>
              <LogoutIcon />
            </IconButton>
          </Box>
        </Toolbar>
      </AppBar>

      <Drawer open={drawerOpen} onClose={() => setDrawerOpen(false)}>
        <Box sx={{ width: 280, mt: 8 }}>
          <List>
            <ListItem>
              <ListItemIcon><DashboardIcon /></ListItemIcon>
              <ListItemText primary="Dashboard" />
            </ListItem>
            <ListItem button onClick={() => setConfigOpen(true)}>
              <ListItemIcon><SettingsIcon /></ListItemIcon>
              <ListItemText primary="Configuración" />
            </ListItem>
          </List>
          <Divider />
          <ListItem>
            <ListItemIcon><DeviceHubIcon /></ListItemIcon>
            <ListItemText primary="Mis Dispositivos" />
          </ListItem>
          {devices.map(device => (
            <ListItem
              key={device.deviceId}
              button
              selected={selectedDevice?.deviceId === device.deviceId}
              onClick={() => setSelectedDevice(device)}
              sx={{ pl: 4 }}
            >
              <ListItemText primary={device.name} secondary={device.deviceId} />
            </ListItem>
          ))}
          <Divider />
          <ListItem>
            <TextField
              size="small"
              label="ID del dispositivo"
              value={newDeviceId}
              onChange={(e) => setNewDeviceId(e.target.value)}
              fullWidth
              sx={{ mb: 1 }}
            />
          </ListItem>
          <ListItem>
            <TextField
              size="small"
              label="Nombre (opcional)"
              value={newDeviceName}
              onChange={(e) => setNewDeviceName(e.target.value)}
              fullWidth
              sx={{ mb: 1 }}
            />
          </ListItem>
          <ListItem>
            <Button fullWidth variant="outlined" startIcon={<AddIcon />} onClick={registerDevice}>
              Registrar Dispositivo
            </Button>
          </ListItem>
        </Box>
      </Drawer>

      <Box component="main" sx={{ flexGrow: 1, p: 3, mt: 8 }}>
        {alert && <Alert severity={alert.type} sx={{ mb: 2 }} onClose={() => setAlert(null)}>{alert.message}</Alert>}

        {!selectedDevice ? (
          <Card sx={{ p: 4, textAlign: 'center' }}>
            <Typography variant="h5">No hay dispositivos</Typography>
            <Typography variant="body2" color="textSecondary">Registra tu primer dispositivo desde el menú lateral.</Typography>
          </Card>
        ) : (
          <Grid container spacing={3}>
            <Grid item xs={12} md={6}>
              <Card sx={{ p: 3 }}>
                <Typography variant="subtitle2" color="textSecondary">Nivel Actual - {selectedDevice.name}</Typography>
                <Typography variant="h2" fontWeight="bold" color={COLORS.primary}>{Math.round(levelPercentage)} %</Typography>
                <LinearProgress variant="determinate" value={levelPercentage} sx={{ height: 12, borderRadius: 6, my: 2 }} />
                <Box display="flex" justifyContent="space-between">
                  <Typography variant="caption">Mín: {selectedDevice.minLevel || minLevel}%</Typography>
                  <Typography variant="caption">Máx: {selectedDevice.maxLevel || maxLevel}%</Typography>
                </Box>
              </Card>
            </Grid>

            <Grid item xs={12} md={6}>
              <Card sx={{ p: 3 }}>
                <Typography variant="subtitle2" color="textSecondary">Estado de la Bomba</Typography>
                <Typography variant="h3" fontWeight="bold" color={pumpStatus ? COLORS.success : COLORS.danger}>
                  {pumpStatus ? 'ENCENDIDA' : 'APAGADA'}
                </Typography>
              </Card>
            </Grid>

            <Grid item xs={12}>
              <Card sx={{ p: 3 }}>
                <Typography variant="subtitle2" color="textSecondary">Historial</Typography>
                <ResponsiveContainer width="100%" height={300}>
                  <AreaChart data={chartData}>
                    <CartesianGrid strokeDasharray="3 3" />
                    <XAxis dataKey="time" />
                    <YAxis domain={[0, 100]} unit="%" />
                    <RechartsTooltip formatter={(value) => `${Math.round(value)}%`} />
                    <Area type="monotone" dataKey="level" stroke={COLORS.primary} fill={COLORS.primary} fillOpacity={0.3} />
                  </AreaChart>
                </ResponsiveContainer>
              </Card>
            </Grid>

            <Grid item xs={12}>
              <Card sx={{ p: 3 }}>
                <Typography variant="subtitle2" color="textSecondary">Estadísticas</Typography>
                <Grid container spacing={2}>
                  <Grid item xs={4}><Box textAlign="center"><Typography variant="h4">{stats.avgLevel}</Typography><Typography variant="caption">Promedio (%)</Typography></Box></Grid>
                  <Grid item xs={4}><Box textAlign="center"><Typography variant="h4" color={COLORS.danger}>{stats.maxLevel}</Typography><Typography variant="caption">Máximo (%)</Typography></Box></Grid>
                  <Grid item xs={4}><Box textAlign="center"><Typography variant="h4" color={COLORS.warning}>{stats.minLevel}</Typography><Typography variant="caption">Mínimo (%)</Typography></Box></Grid>
                </Grid>
              </Card>
            </Grid>
          </Grid>
        )}
      </Box>

      <Drawer anchor="right" open={configOpen} onClose={() => setConfigOpen(false)}>
        <Box sx={{ width: 320, p: 3 }}>
          <Typography variant="h6">Configuración</Typography>
          <Typography variant="body2" color="textSecondary" gutterBottom>Dispositivo: {selectedDevice?.name}</Typography>
          <Divider sx={{ my: 2 }} />
          <Typography gutterBottom>Altura del Tanque (cm)</Typography>
          <TextField fullWidth value={inputTankHeight || tankHeight} onChange={(e) => setInputTankHeight(e.target.value)} inputMode="numeric" sx={{ mb: 2 }} />
          <Typography gutterBottom>Nivel Mínimo (%)</Typography>
          <TextField fullWidth value={inputMinLevel || minLevel} onChange={(e) => setInputMinLevel(e.target.value)} inputMode="numeric" sx={{ mb: 2 }} />
          <Typography gutterBottom>Nivel Máximo (%)</Typography>
          <TextField fullWidth value={inputMaxLevel || maxLevel} onChange={(e) => setInputMaxLevel(e.target.value)} inputMode="numeric" sx={{ mb: 2 }} />
          <Button fullWidth variant="contained" onClick={saveConfig}>Guardar</Button>
        </Box>
      </Drawer>
    </Box>
  );
}

export default App;